    open(os.path.join(drv, "tdrv.js"), "w").write(r'''// ROUTE A1 for typescript: the require-able checker inside the SHIPPED
// typescript.js.  A chunk of probe files becomes one ts.Program and each
// file's own syntactic + semantic diagnostics are read back; the lib
// files are parsed once and cached, which is what makes it cheap.
const fs = require('fs');
const path = require('path');
const TSJS = '/persist/tv/ts5/node_modules/typescript/lib/typescript.js';
const ts = require(TSJS);
console.log('__NOTE__|typescript ' + ts.version + ' from ' + TSJS);
const files = fs.readFileSync(process.argv[2], 'utf8')
                .split('\n').filter(s => s.length > 0);
const opts = {
  target: ts.ScriptTarget.ES2022,
  strict: true,
  noEmit: true,
  skipLibCheck: true,
  types: [],
  moduleResolution: ts.ModuleResolutionKind.NodeJs,
};
const base = ts.createCompilerHost(opts);
const libCache = new Map();
const host = Object.create(base);
host.writeFile = () => {};
host.getSourceFile = function (fn, lv, oe, sfc) {
  if (libCache.has(fn)) return libCache.get(fn);
  const sf = base.getSourceFile(fn, lv, oe, sfc);
  if (/lib\..*\.d\.ts$/.test(fn)) libCache.set(fn, sf);
  return sf;
};
const CH = 500;
const t0 = Date.now();
let n = 0;
for (let i = 0; i < files.length; i += CH) {
  const chunk = files.slice(i, i + CH);
  const program = ts.createProgram(chunk, opts, host);
  for (const f of chunk) {
    const sf = program.getSourceFile(f);
    let ok;
    if (!sf) { ok = false; }
    else {
      const d = program.getSyntacticDiagnostics(sf)
                .concat(program.getSemanticDiagnostics(sf));
      ok = d.length === 0;
    }
    const b = path.basename(f).replace(/\.ts$/, '');
    console.log(b + '|' + (ok ? 'ACCEPT' : 'REFUSE'));
    n++;
  }
}
console.log('__TOTAL_MS__|' + (Date.now() - t0) + '|' + n);
''')
